        Colors[4] := 'FFFF00'; // Yellow
        Colors[5] := 'C80000'; // Red
        Colors[6] := 'A0A0A0'; // gray up
        Colors[7] := '303030'; // dark down

        sColors[ 9] := '666666666666666666';
        sColors[ 8] := '666666666666666666';
        sColors[ 7] := '626666606666616666';
        sColors[ 6] := '666666666666666666';
