        sColors[ 3] := '666666666666666666';
        sColors[ 2] := '666666666666666666';
        sColors[ 1] := '666666666666666666';
        sColors[ 0] := '626260606061616162';
        sColors[10] := '573737374747475757';
        sColors[11] := '777777777777777777';
        sColors[12] := '777777777777777777';
        sColors[13] := '777777777777777777';
